for fid, title, intro, works, qs in G:
    lines = ["---", f"field: {fid}", "status: draft", "drafted: 2026-11-27", "---", f"# {title}", "", intro, "", "## Key works"]
    lines += [f"- {lv} · {t} · {c} · {y} · {a} | {why}" for lv, t, c, y, a, why in works]
    lines += ["", "## Quick check"]
    for q, right, w1, w2 in qs:
        lines += [f"**Multiple choice.** {q}", f"- {right} ✓", f"- {w1}", f"- {w2}", ""]
    (ROOT / "guides" / f"{fid}.md").write_text("\n".join(lines), encoding="utf-8", newline="\n")
print(len(G), "guides written")
